//! `ketra shell install | uninstall | status` — one-command OS shell
//! integration for desktop file managers.
//!
//! What gets installed, per platform:
//!
//! * **Windows (Explorer)** — HKCU context-menu verbs: `KetraCopy: Copy`,
//!   `KetraCopy: Cut` (clipboard put), `KetraCopy: Paste here`
//!   (clipboard paste into folder/background), plus picker-based
//!   `Copy to Folder…` / `Move to Folder…` / `Test (Verify)…` verbs that go
//!   through a small PowerShell helper with a folder dialog. An optional
//!   AutoHotkey v2 script provides Ctrl+Shift+C/X/V keyboard shortcuts.
//! * **Linux** — Nemo actions (copy/cut/move-to/test), Nemo/Nautilus/Caja
//!   scripts (including *Paste Here* via the file manager's own clipboard),
//!   a Dolphin service menu, the Thunar custom-action snippet, and the
//!   `ketra-pick` destination-folder picker. `shortcuts` registers Cinnamon
//!   custom keybindings for clipboard paste into the active file manager.
//! * **macOS (Finder)** — Services / Quick Actions: *Copy with KetraCopy*,
//!   *Cut with KetraCopy*, *Paste with KetraCopy* (folder chooser),
//!   *Move with KetraCopy* — written as Automator `.workflow` bundles into
//!   `~/Library/Services` and registered with `pbs`. Keyboard shortcuts are
//!   assigned in System Settings (documented by `ketra shell status`).
//!
//! Everything is generated in code — no external asset files are needed.

use std::path::{Path, PathBuf};
use std::process::Command;

fn exe_path() -> PathBuf {
    std::env::current_exe().unwrap_or_else(|_| PathBuf::from("ketra"))
}

fn exe_str() -> String {
    exe_path().display().to_string()
}

fn have(cmd: &str) -> bool {
    Command::new("which")
        .arg(cmd)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

// ---------------------------------------------------------------------------
// Windows
// ---------------------------------------------------------------------------

#[cfg(windows)]
mod imp {
    use super::*;

    const KEYS: &[(&str, &str)] = &[
        (r"Software\Classes\AllFilesystemObjects\shell\KetraCopy.ClipboardCopy", "KetraCopy: Copy"),
        (r"Software\Classes\AllFilesystemObjects\shell\KetraCopy.ClipboardCut", "KetraCopy: Cut"),
        (r"Software\Classes\Directory\shell\KetraCopy.Paste", "KetraCopy: Paste here"),
        (r"Software\Classes\Directory\Background\shell\KetraCopy.Paste", "KetraCopy: Paste here"),
        (r"Software\Classes\*\shell\KetraCopy.CopyTo", "KetraCopy: Copy to Folder..."),
        (r"Software\Classes\*\shell\KetraCopy.MoveTo", "KetraCopy: Move to Folder..."),
        (r"Software\Classes\*\shell\KetraCopy.Test", "KetraCopy: Test (Verify)..."),
        (r"Software\Classes\Directory\shell\KetraCopy.CopyTo", "KetraCopy: Copy to Folder..."),
        (r"Software\Classes\Directory\shell\KetraCopy.MoveTo", "KetraCopy: Move to Folder..."),
        (r"Software\Classes\Directory\shell\KetraCopy.Test", "KetraCopy: Test (Verify)..."),
    ];

    fn reg(args: &[&str]) -> Result<(), String> {
        let st = Command::new("reg")
            .args(args)
            .output()
            .map_err(|e| format!("reg.exe: {e}"))?;
        if !st.status.success() {
            return Err(format!(
                "reg {} failed: {}",
                args.join(" "),
                String::from_utf8_lossy(&st.stderr).trim()
            ));
        }
        Ok(())
    }

    fn write_verb(key: &str, label: &str, exe: &str, args_tpl: &str) -> Result<(), String> {
        reg(&["add", key, "/f", "/ve", "/t", "REG_SZ", "/d", label])?;
        reg(&["add", key, "/f", "/v", "Icon", "/t", "REG_SZ", "/d", exe])?;
        reg(&["add", key, "/f", "/v", "MultiSelectModel", "/t", "REG_SZ", "/d", "Player"])?;
        let cmd = format!("\"{}\" {}", exe, args_tpl);
        reg(&["add", &format!("{key}\\command"), "/f", "/ve", "/t", "REG_SZ", "/d", &cmd])
    }

    /// The PowerShell destination-folder helper (PS 2.0 compatible).
    fn pick_helper_src(exe: &str) -> String {
        r#"# KetraCopy destination-folder helper (generated by `ketra shell install`).
# PS 2.0 compatible: no $PSScriptRoot, no ternary.
param([string]$Action = "copy", [string]$Target = "")

Add-Type -AssemblyName System.Windows.Forms

$exe = "__KETRA_EXE__"
if (-not (Test-Path -LiteralPath $exe)) {
    $found = Get-Command "ketra.exe" -ErrorAction SilentlyContinue
    if ($found -ne $null) { $exe = $found.Path }
}
if (-not (Test-Path -LiteralPath $exe)) {
    [void][System.Windows.Forms.MessageBox]::Show("KetraCopy: ketra.exe not found.", "KetraCopy")
    exit 1
}

$dlg = New-Object System.Windows.Forms.FolderBrowserDialog
$dlg.Description = "KetraCopy: choose the destination folder"
$dlg.ShowNewFolderButton = $true
$top = New-Object System.Windows.Forms.Form
$top.TopMost = $true
$result = $dlg.ShowDialog($top)
if ($result -ne [System.Windows.Forms.DialogResult]::OK) { exit 0 }
$dest = $dlg.SelectedPath

$ketraArgs = @($Action, $Target, "-d", $dest, "-y")
$proc = Start-Process -FilePath $exe -ArgumentList $ketraArgs -NoNewWindow -Wait -PassThru -RedirectStandardOutput "$Env:TEMP\ketracopy-last.txt" -RedirectStandardError "$Env:TEMP\ketracopy-last-err.txt"
$code = $proc.ExitCode
$body = ""
try { $body = Get-Content "$Env:TEMP\ketracopy-last.txt" -Raw } catch {}
if ($body -eq $null -or $body -eq "") { try { $body = Get-Content "$Env:TEMP\ketracopy-last-err.txt" -Raw } catch {} }
if ($body -eq $null) { $body = "" }
$verb = "Copy"
if ($Action -eq "move") { $verb = "Move" }
if ($Action -eq "test") { $verb = "Verify" }
$msg = "$verb with KetraCopy: "
if ($code -eq 0) { $msg += "completed OK." } elseif ($code -eq 2) { $msg += "canceled." } else { $msg += "finished with errors ($code)." }
if ($body -ne $null -and $body -ne "") { $msg += [Environment]::NewLine + $body.Trim() }
[void][System.Windows.Forms.MessageBox]::Show($msg, "KetraCopy")
"#.replace("__KETRA_EXE__", exe)
    }

    /// Optional AutoHotkey v2 script for keyboard shortcuts (Ctrl+Shift+C/X/V).
    fn ahk_src() -> String {
        r#"; KetraCopy keyboard shortcuts (AutoHotkey v2) - generated helper.
; Requires: https://www.autohotkey.com (v2). Double-click to run; add a
; shortcut to shell:startup to start with Windows.
;
;   Ctrl+Shift+C  put the selected Explorer items on the clipboard (copy)
;   Ctrl+Shift+X  put the selected Explorer items on the clipboard (cut)
;   Ctrl+Shift+V  paste the clipboard through KetraCopy into the active
;                 Explorer folder (accelerated, verified, resumable)

#Requires AutoHotkey v2.0
#SingleInstance Force

Ketra() {
    candidates := [A_AppData . "\KetraCopy\ketra.exe"
                 , A_ProgramFiles . "\KetraCopy\ketra.exe"
                 , A_ScriptDir . "\ketra.exe"]
    for p in candidates {
        if FileExist(p) {
            return p
        }
    }
    MsgBox "ketra.exe not found - reinstall KetraCopy."
    ExitApp
}

ActiveExplorerWindow() {
    hwnd := WinExist("A")
    for w in ComObject("Shell.Application").Windows {
        try {
            if w.hwnd = hwnd {
                return w
            }
        }
    }
    return ""
}

ExplorerPath() {
    w := ActiveExplorerWindow()
    if w = "" {
        return ""
    }
    path := w.LocationURL
    path := StrReplace(path, "file:///", "")
    path := StrReplace(path, "/", "\")
    path := StrReplace(path, "%20", " ")
    return path
}

SelectedFiles() {
    w := ActiveExplorerWindow()
    if w = "" {
        return ""
    }
    files := ""
    for item in w.Document.SelectedItems {
        files .= (files = "" ? "" : "`n") item.Path
    }
    return files
}

^+c:: {
    files := SelectedFiles()
    if files != "" {
        Run Format('"{1}" clip put "{2}"', Ketra(), StrReplace(files, "`n", '" "'))
    }
}

^+x:: {
    files := SelectedFiles()
    if files != "" {
        Run Format('"{1}" clip put --cut "{2}"', Ketra(), StrReplace(files, "`n", '" "'))
    }
}

^+v:: {
    path := ExplorerPath()
    if path != "" {
        Run Format('"{1}" clip paste -d "{2}" -y', Ketra(), path)
    } else {
        Run Format('"{1}" clip paste -y', Ketra())
    }
}
"#.to_string()
    }

    pub fn install() -> Result<(), String> {
        let exe = exe_str();
        // Helper + optional AHK live in %LOCALAPPDATA%\KetraCopy
        let data_dir = std::env::var("LOCALAPPDATA")
            .map(|d| PathBuf::from(d).join("KetraCopy"))
            .unwrap_or_else(|_| PathBuf::from("KetraCopy"));
        std::fs::create_dir_all(&data_dir).map_err(|e| e.to_string())?;
        let helper = data_dir.join("ketra-pick.ps1");
        std::fs::write(&helper, pick_helper_src(&exe)).map_err(|e| e.to_string())?;
        let ahk = data_dir.join("KetraCopy.ahk");
        std::fs::write(&ahk, ahk_src()).map_err(|e| e.to_string())?;

        let ps = helper.display().to_string();
        write_verb(KEYS[0].0, KEYS[0].1, &exe, "clip put \"%1\"")?;
        write_verb(KEYS[1].0, KEYS[1].1, &exe, "clip put --cut \"%1\"")?;
        write_verb(KEYS[2].0, KEYS[2].1, &exe, "clip paste -d \"%1\" -y --progress quiet")?;
        write_verb(KEYS[3].0, KEYS[3].1, &exe, "clip paste -d \"%V\" -y --progress quiet")?;
        write_verb(KEYS[4].0, KEYS[4].1, &exe, &format!("powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File \"{}\" copy \"%1\"", ps))?;
        write_verb(KEYS[5].0, KEYS[5].1, &exe, &format!("powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File \"{}\" move \"%1\"", ps))?;
        write_verb(KEYS[6].0, KEYS[6].1, &exe, &format!("powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File \"{}\" test \"%1\"", ps))?;
        write_verb(KEYS[7].0, KEYS[7].1, &exe, &format!("powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File \"{}\" copy \"%1\"", ps))?;
        write_verb(KEYS[8].0, KEYS[8].1, &exe, &format!("powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File \"{}\" move \"%1\"", ps))?;
        write_verb(KEYS[9].0, KEYS[9].1, &exe, &format!("powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File \"{}\" test \"%1\"", ps))?;
        println!("windows integration installed (HKCU):");
        println!("  context menus: copy / cut / paste-here / copy-to / move-to / test");
        println!("  helper: {}", helper.display());
        println!("  optional keyboard shortcuts: {}", ahk.display());
        println!("    (requires AutoHotkey v2 from autohotkey.com - double-click the");
        println!("     .ahk file, or put a shortcut into shell:startup)");
        Ok(())
    }

    pub fn uninstall() -> Result<(), String> {
        for (key, _) in KEYS {
            let _ = reg(&["delete", key, "/f"]);
        }
        if let Ok(d) = std::env::var("LOCALAPPDATA") {
            let _ = std::fs::remove_file(PathBuf::from(d).join("KetraCopy").join("ketra-pick.ps1"));
        }
        println!("windows integration removed (HKCU keys deleted; KetraCopy.ahk kept)");
        Ok(())
    }

    pub fn status() {
        let ok = |key: &str| -> bool {
            Command::new("reg")
                .args(["query", key])
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .status()
                .map(|s| s.success())
                .unwrap_or(false)
        };
        for (key, label) in KEYS {
            println!("  [{}] {}", if ok(key) { "x" } else { " " }, label);
        }
        if let Ok(d) = std::env::var("LOCALAPPDATA") {
            let ahk = PathBuf::from(d).join("KetraCopy").join("KetraCopy.ahk");
            println!(
                "  [{}] keyboard shortcuts (AutoHotkey v2): {}",
                if ahk.exists() { "x" } else { " " },
                ahk.display()
            );
        }
    }
}

// ---------------------------------------------------------------------------
// Linux
// ---------------------------------------------------------------------------

#[cfg(all(unix, not(target_os = "macos")))]
mod imp {
    use super::*;

    fn bin_dir() -> PathBuf {
        PathBuf::from(std::env::var("HOME").unwrap_or_else(|_| ".".into())).join(".local/bin")
    }

    /// The destination-folder picker used by every file-manager integration.
    fn pick_src() -> String {
        let tpl = r#"#!/usr/bin/env bash
# ketra-pick — KetraCopy destination-folder picker (generated by `ketra shell install`).
# Usage: ketra-pick copy|move|test <path> [<path>...]
# Environment: KETRA_DEST=<dir>  pre-select the destination (skips the dialog)
#              KETRA_PICKER=<zenity|kdialog|yad>  force a picker backend
set -u

KETRA="__KETRA_EXE__"
if [ ! -x "$KETRA" ]; then
    KETRA="$(command -v ketra || true)"
fi
if [ -z "$KETRA" ]; then
    echo "KetraCopy: ketra binary not found" >&2
    exit 1
fi
if [ -n "${FLATPAK_ID:-}" ]; then
    KETRA="flatpak-spawn --host ketra"
fi

# A pre-selected destination skips the dialog (scripting / headless use).
DEST="${KETRA_DEST:-}"
if [ -z "$DEST" ]; then
PICKER="${KETRA_PICKER:-}"
if [ -z "$PICKER" ]; then
    if command -v zenity >/dev/null 2>&1; then PICKER=zenity
    elif command -v kdialog >/dev/null 2>&1; then PICKER=kdialog
    elif command -v yad >/dev/null 2>&1; then PICKER=yad
    else
        echo "KetraCopy: no folder picker found (install zenity, or set KETRA_DEST)" >&2
        exit 1
    fi
fi

case "$PICKER" in
    zenity) DEST=$(zenity --file-selection --directory --title "KetraCopy: choose destination" 2>/dev/null) ;;
    kdialog) DEST=$(kdialog --getexistingdirectory "$HOME" --title "KetraCopy: choose destination" 2>/dev/null) ;;
    yad) DEST=$(yad --file --directory --title "KetraCopy: choose destination" 2>/dev/null) ;;
esac
fi
[ -z "${DEST:-}" ] && exit 0

ACTION="$1"; shift
exec "$KETRA" "$ACTION" "$@" -d "$DEST" --progress auto
"#;
        tpl.replace("__KETRA_EXE__", &exe_str())
    }

    /// Paste-into-current-folder script for Nautilus/Caja/Nemo script menus.
    fn paste_here_src() -> String {
        r#"#!/usr/bin/env bash
# ketra-paste-here — paste the file manager's clipboard through KetraCopy
# into the current file manager folder (generated by `ketra shell install`).
set -u

KETRA=""
for c in "$HOME/.local/bin/ketra" "/usr/local/bin/ketra" "$(command -v ketra 2>/dev/null)"; do
    if [ -n "$c" ] && [ -x "$c" ]; then KETRA="$c"; break; fi
done
if [ -z "$KETRA" ]; then
    echo "KetraCopy: ketra binary not found" >&2
    exit 1
fi

DEST=""
# Nautilus/Caja/Nemo scripts export the current folder URI:
for VAR in KETRA_SCRIPT_CURRENT_URI NEMO_SCRIPT_CURRENT_URI NAUTILUS_SCRIPT_CURRENT_URI; do
    eval "val=\${$VAR:-}"
    if [ -n "$val" ]; then
        # Pure-bash percent decoding (sed quoting for '# ' and '%' is fragile).
        DEST="${val#file://}"
        DEST="${DEST//%20/ }"
        DEST="${DEST//%23/#}"
        DEST="${DEST//%25/%}"
        break
    fi
done

# When invoked on a *selected folder*, paste into that folder instead.
for VAR in KETRA_SCRIPT_SELECTED_FILE_PATHS NEMO_SCRIPT_SELECTED_FILE_PATHS NAUTILUS_SCRIPT_SELECTED_FILE_PATHS; do
    eval "val=\${$VAR:-}"
    if [ -n "$val" ] && [ "$(printf '%s\n' "$val" | grep -c .)" = "1" ] && [ -d "$val" ]; then
        DEST="$val"
        break
    fi
done

if [ -z "$DEST" ]; then
    echo "KetraCopy: cannot determine the current folder" >&2
    exit 1
fi

exec "$KETRA" clip paste -d "$DEST" --progress auto
"#
        .to_string()
    }

    fn write_exec(path: &Path, content: &str) -> Result<(), String> {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).map_err(|e| format!("{}: {e}", parent.display()))?;
        }
        std::fs::write(path, content).map_err(|e| format!("{}: {e}", path.display()))?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o755));
        }
        Ok(())
    }

    fn install_nemo(pick: &Path) -> Result<(), String> {
        let dir = PathBuf::from(std::env::var("HOME").unwrap_or_default()).join(".local/share/nemo/actions");
        std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
        let pick = pick.display().to_string();
        let actions = [
            (
                "ketra-copy.nemo_action",
                format!("[Nemo Action]\nActive=true\nName=KetraCopy: Copy to Folder...\nComment=Copy with KetraCopy (verified, resumable, SHA-256 manifest)\nExec={} copy %F\nIcon-Name=edit-copy\nSelection=any\nExtensions=any;\n", pick),
            ),
            (
                "ketra-cut.nemo_action",
                format!("[Nemo Action]\nActive=true\nName=KetraCopy: Cut\nComment=Cut with KetraCopy (native paste works everywhere; KetraCopy paste moves)\nExec={} clip put --cut %F\nIcon-Name=edit-cut\nSelection=any\nExtensions=any;\n", pick),
            ),
            (
                "ketra-move.nemo_action",
                format!("[Nemo Action]\nActive=true\nName=KetraCopy: Move to Folder...\nComment=Move with KetraCopy (verified, resumable)\nExec={} move %F\nIcon-Name=folder-move\nSelection=any\nExtensions=any;\n", pick),
            ),
            (
                "ketra-test.nemo_action",
                format!("[Nemo Action]\nActive=true\nName=KetraCopy: Test (Verify)...\nComment=Read-test the selection with the engine's hash path\nExec={} test %F\nIcon-Name=dialog-information\nSelection=any\nExtensions=any;\n", pick),
            ),
        ];
        for (name, content) in actions {
            std::fs::write(dir.join(name), content).map_err(|e| e.to_string())?;
        }
        // paste-into-current-folder as a Nemo *script* (works with no selection)
        let sdir = dir.parent().unwrap().join("scripts");
        write_exec(&sdir.join("KetraCopy Paste Here"), &paste_here_src())?;
        println!("  Nemo:        {} (+ paste-here script)", dir.display());
        Ok(())
    }

    fn install_scripts_fm(dir_name: &str, label: &str) -> Result<(), String> {
        let home = PathBuf::from(std::env::var("HOME").unwrap_or_default());
        let dir = home.join(format!(".local/share/{dir_name}/scripts"));
        std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
        let env_prefix = match dir_name {
            "nemo" => "NEMO",
            "caja" => "CAJA",
            _ => "NAUTILUS",
        };
        let mk = |name: &str, action: &str| -> String {
            // copy/move need a destination folder: route through the
            // ketra-pick helper (folder dialog, or $KETRA_DEST when set for
            // scripts/headless use). `test` runs directly, it needs no dest.
            if action == "copy" || action == "move" {
                format!(
                    "#!/usr/bin/env bash\n# KetraCopy {name} (generated by `ketra shell install`)\nset -u\nARGS=()\nwhile IFS= read -r p; do [ -n \"$p\" ] && ARGS+=(\"$p\"); done <<EOF\n${{{env_prefix}_SCRIPT_SELECTED_FILE_PATHS:-}}\nEOF\n[ ${{#ARGS[@]}} -eq 0 ] && exit 0\nPICK=\"$HOME/.local/bin/ketra-pick\"\n[ -x \"$PICK\" ] || PICK=\"$(command -v ketra-pick 2>/dev/null)\"\nif [ -n \"$PICK\" ] && [ -x \"$PICK\" ]; then\n    exec \"$PICK\" {action} \"${{ARGS[@]}}\"\nfi\necho \"KetraCopy: pick helper not found — run `ketra shell install pick`\" >&2\nexit 1\n"
                )
            } else {
                format!(
                    "#!/usr/bin/env bash\n# KetraCopy {name} (generated by `ketra shell install`)\nset -u\nKETRA=\"$HOME/.local/bin/ketra\"\n[ -x \"$KETRA\" ] || KETRA=\"$(command -v ketra 2>/dev/null)\"\n[ -z \"$KETRA\" ] && {{ echo \"ketra not found\" >&2; exit 1; }}\nARGS=()\nwhile IFS= read -r p; do [ -n \"$p\" ] && ARGS+=(\"$p\"); done <<EOF\n${{{env_prefix}_SCRIPT_SELECTED_FILE_PATHS:-}}\nEOF\n[ ${{#ARGS[@]}} -eq 0 ] && exit 0\nexec \"$KETRA\" {action} \"${{ARGS[@]}}\"\n"
                )
            }
        };
        write_exec(&dir.join("KetraCopy Copy"), &mk("copy", "copy"))?;
        write_exec(&dir.join("KetraCopy Move to Folder..."), &mk("move", "move"))?;
        write_exec(&dir.join("KetraCopy Test (Verify)"), &mk("test", "test"))?;
        if dir_name == "nemo" {
            // paste script uses NEMO_SCRIPT_CURRENT_URI
            let mut paste = paste_here_src();
            paste = paste.replace("KETRA_SCRIPT_CURRENT_URI ", "");
            write_exec(&dir.join("KetraCopy Paste Here"), &paste)?;
        } else {
            write_exec(&dir.join("KetraCopy Paste Here"), &paste_here_src())?;
        }
        println!("  {label}: {}", dir.display());
        Ok(())
    }

    fn install_dolphin(pick: &Path) -> Result<(), String> {
        let dir = PathBuf::from(std::env::var("HOME").unwrap_or_default()).join(".local/share/kio/servicemenus");
        std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
        let pick = pick.display().to_string();
        let desktop = format!(
            "[Desktop Entry]\nType=Service\nX-KDE-Priority=TopLevel\nX-KDE-Submenu=KetraCopy\nName=KetraCopy\nIcon=edit-copy\nMimeType=all/allfiles;inode/directory;\nActions=copy;cut;move;test;paste;\n\n[Desktop Action copy]\nName=Copy to Folder...\nIcon=edit-copy\nExec={} copy %F\n\n[Desktop Action cut]\nName=Cut (KetraCopy clipboard)\nIcon=edit-cut\nExec={} clip put --cut %F\n\n[Desktop Action move]\nName=Move to Folder...\nIcon=folder-move\nExec={} move %F\n\n[Desktop Action test]\nName=Test (Verify) contents...\nIcon=dialog-information\nExec={} test %F\n\n[Desktop Action paste]\nName=Paste here (KetraCopy)\nIcon=edit-paste\nExec={} clip paste -d %f --progress auto\n",
            pick, pick, pick, pick, pick
        );
        std::fs::write(dir.join("ketracopy.desktop"), desktop).map_err(|e| e.to_string())?;
        println!("  Dolphin:     {}", dir.display());
        Ok(())
    }

    fn install_thunar_snippet(pick: &Path) -> Result<(), String> {
        let dir = PathBuf::from(std::env::var("HOME").unwrap_or_default()).join(".config/Thunar");
        std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
        let pick = pick.display().to_string();
        let xml = format!(
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<actions>\n  <action>\n    <icon>edit-copy</icon>\n    <name>KetraCopy: Copy to Folder...</name>\n    <unique-id>ketra-copy</unique-id>\n    <command>{pick} copy %F</command>\n    <description>Copy with KetraCopy (verified, resumable)</description>\n    <patterns>*</patterns>\n    <directories/>\n    <audio-files/>\n    <image-files/>\n    <other-files/>\n    <text-files/>\n    <video-files/>\n  </action>\n  <action>\n    <icon>folder-move</icon>\n    <name>KetraCopy: Move to Folder...</name>\n    <unique-id>ketra-move</unique-id>\n    <command>{pick} move %F</command>\n    <description>Move with KetraCopy (verified, resumable)</description>\n    <patterns>*</patterns>\n    <directories/>\n    <audio-files/>\n    <image-files/>\n    <other-files/>\n    <text-files/>\n    <video-files/>\n  </action>\n</actions>\n"
        );
        let target = dir.join("ketra-uca-snippet.xml");
        std::fs::write(&target, xml).map_err(|e| e.to_string())?;
        println!(
            "  Thunar:      {} (merge into ~/.config/Thunar/uca.xml — see SHELL-INTEGRATION.md)",
            target.display()
        );
        Ok(())
    }

    fn install_shortcuts() -> Result<(), String> {
        // Cinnamon: register a custom keybinding for smart paste.
        let script_dir = bin_dir();
        std::fs::create_dir_all(&script_dir).map_err(|e| e.to_string())?;
        let smart = script_dir.join("ketra-paste-smart");
        let smart_src = format!(
            "#!/usr/bin/env bash\n# ketra-paste-smart — paste the file manager clipboard through KetraCopy\n# into the active Nemo/Caja window when possible, else a folder picker.\nset -u\nKETRA=\"$HOME/.local/bin/ketra\"\n[ -x \"$KETRA\" ] || KETRA=\"$(command -v ketra 2>/dev/null)\"\n[ -z \"$KETRA\" ] && exit 1\nDEST=\"\"\nif command -v xdotool >/dev/null 2>&1; then\n    WID=$(xdotool getactivewindow 2>/dev/null || true)\n    if [ -n \"$WID\" ]; then\n        TITLE=$(xdotool getwindowname \"$WID\" 2>/dev/null || true)\n        PID=$(xdotool getwindowpid \"$WID\" 2>/dev/null || true)\n        # The window title is the folder's display name; resolve only an\n        # exact, unambiguous match under $HOME (conservative by design):\n        # titles containing '..' or an absolute path are rejected so a\n        # renamed window cannot redirect the paste outside $HOME.\n        case \"$TITLE\" in *..*|/*) TITLE=\"\" ;; esac\n        if [ -n \"$TITLE\" ] && [ -d \"$HOME/$TITLE\" ]; then\n            DEST=\"$HOME/$TITLE\"\n        fi\n    fi\nfi\nif [ -z \"$DEST\" ]; then\n    if command -v zenity >/dev/null 2>&1; then\n        DEST=$(zenity --file-selection --directory --title \"KetraCopy: paste into\" 2>/dev/null)\n    elif command -v kdialog >/dev/null 2>&1; then\n        DEST=$(kdialog --getexistingdirectory \"$HOME\" --title \"KetraCopy: paste into\" 2>/dev/null)\n    fi\nfi\n[ -z \"${{DEST:-}}\" ] && exit 0\nexec \"$KETRA\" clip paste -d \"$DEST\" --progress auto\n"
        );
        write_exec(&smart, &smart_src)?;

        let ok = Command::new("gsettings")
            .args(["get", "org.cinnamon.desktop.keybindings", "custom-list"])
            .output()
            .ok()
            .map(|o| o.status.success())
            .unwrap_or(false);
        if !ok {
            println!("  shortcuts:   gsettings/Cinnamon not found — {} written; wire it to a key manually", smart.display());
            return Ok(());
        }
        let run_gs = |args: &[&str]| {
            let _ = Command::new("gsettings").args(args).status();
        };
        run_gs(&["set", "org.cinnamon.desktop.keybindings", "custom-list",
            "['__ketracopy_paste__']"]);
        let base = "org.cinnamon.desktop.keybindings.custom-keybinding:/__ketracopy_paste__/";
        run_gs(&["set", base, "name", "KetraCopy: Paste here"]);
        run_gs(&["set", base, "command", &smart.display().to_string()]);
        run_gs(&["set", base, "binding", "['<Super>v']"]);
        println!("  shortcuts:   Cinnamon Super+V → {}", smart.display());
        Ok(())
    }

    pub fn install(targets: &[String]) -> Result<(), String> {
        let bin = bin_dir();
        std::fs::create_dir_all(&bin).map_err(|e| e.to_string())?;
        let pick = bin.join("ketra-pick");
        write_exec(&pick, &pick_src())?;
        // Also expose the ketra binary itself on ~/.local/bin when running
        // from elsewhere (actions call plain `ketra` as a fallback).
        let exe = exe_path();
        let link = bin.join("ketra");
        if exe != link && !link.exists() {
            #[cfg(unix)]
            let _ = std::os::unix::fs::symlink(&exe, &link);
        }

        let all = targets.is_empty() || targets.iter().any(|t| t == "all");
        let want = |t: &str| all || targets.iter().any(|x| x == t);

        println!("linux integration installed:");
        if want("nemo") {
            install_nemo(&pick)?;
        }
        if want("nautilus") {
            install_scripts_fm("nautilus", "Nautilus")?;
        }
        if want("caja") {
            install_scripts_fm("caja", "Caja")?;
        }
        if want("dolphin") {
            install_dolphin(&pick)?;
        }
        if want("thunar") {
            install_thunar_snippet(&pick)?;
        }
        if want("shortcuts") {
            install_shortcuts()?;
        }
        println!("  picker:      {}", pick.display());
        Ok(())
    }

    pub fn uninstall(targets: &[String]) -> Result<(), String> {
        let home = PathBuf::from(std::env::var("HOME").unwrap_or_default());
        let all = targets.is_empty() || targets.iter().any(|t| t == "all");
        let want = |t: &str| all || targets.iter().any(|x| x == t);
        let rm = |p: &Path| {
            if p.exists() {
                let _ = std::fs::remove_file(p);
            }
        };
        if want("nemo") {
            for n in ["ketra-copy", "ketra-cut", "ketra-move", "ketra-test"] {
                rm(&home.join(format!(".local/share/nemo/actions/{n}.nemo_action")));
            }
            rm(&home.join(".local/share/nemo/scripts/KetraCopy Paste Here"));
        }
        if want("nautilus") {
            for n in ["KetraCopy Copy", "KetraCopy Move to Folder...", "KetraCopy Test (Verify)", "KetraCopy Paste Here"] {
                rm(&home.join(format!(".local/share/nautilus/scripts/{n}")));
            }
        }
        if want("caja") {
            for n in ["KetraCopy Copy", "KetraCopy Move to Folder...", "KetraCopy Test (Verify)", "KetraCopy Paste Here"] {
                rm(&home.join(format!(".local/share/caja/scripts/{n}")));
            }
        }
        if want("dolphin") {
            rm(&home.join(".local/share/kio/servicemenus/ketracopy.desktop"));
        }
        if want("thunar") {
            rm(&home.join(".config/Thunar/ketra-uca-snippet.xml"));
        }
        if want("pick") {
            // The generated destination-picker helper is part of the
            // integration; the `ketra` CLI binary itself stays installed.
            rm(&home.join(".local/bin/ketra-pick"));
        }
        if want("shortcuts") {
            let _ = Command::new("gsettings")
                .args(["set", "org.cinnamon.desktop.keybindings", "custom-list", "[]"])
                .status();
        }
        println!("linux integration removed");
        Ok(())
    }

    pub fn status() {
        let home = PathBuf::from(std::env::var("HOME").unwrap_or_default());
        let marks = [
            (home.join(".local/share/nemo/actions/ketra-copy.nemo_action").exists(), "Nemo actions"),
            (home.join(".local/share/nemo/scripts/KetraCopy Paste Here").exists(), "Nemo paste-here"),
            (home.join(".local/share/nautilus/scripts/KetraCopy Copy").exists(), "Nautilus scripts"),
            (home.join(".local/share/caja/scripts/KetraCopy Copy").exists(), "Caja scripts"),
            (home.join(".local/share/kio/servicemenus/ketracopy.desktop").exists(), "Dolphin service menu"),
            (home.join(".config/Thunar/ketra-uca-snippet.xml").exists(), "Thunar snippet"),
            (home.join(".local/bin/ketra-pick").exists(), "folder picker"),
        ];
        for (ok, label) in marks {
            println!("  [{}] {}", if ok { "x" } else { " " }, label);
        }
    }
}

