#[cfg(target_os = "macos")]
mod imp {
    use super::*;

    fn services_dir() -> PathBuf {
        PathBuf::from(std::env::var("HOME").unwrap_or_default()).join("Library/Services")
    }

    fn ketra_lookup_shell() -> String {
        r#"KETRA=""
for c in "/usr/local/bin/ketra" "/opt/homebrew/bin/ketra" "$HOME/.cargo/bin/ketra" "$(command -v ketra 2>/dev/null)"; do
    if [ -n "$c" ] && [ -x "$c" ]; then KETRA="$c"; break; fi
done
if [ -z "$KETRA" ]; then
    osascript -e 'display alert "KetraCopy" message "ketra binary not found — reinstall KetraCopy."'
    exit 1
fi"#
            .to_string()
    }

    /// Minimal but valid Automator Quick Action bundle.
    fn write_workflow(
        dir: &Path,
        name: &str,
        menu: &str,
        receives_files: bool,
        script: &str,
    ) -> Result<(), String> {
        let bundle = dir.join(format!("{name}.workflow/Contents"));
        std::fs::create_dir_all(&bundle).map_err(|e| e.to_string())?;
        let (send_file_types, input_type) = if receives_files {
            ("<key>NSSendFileTypes</key>\n\t<array>\n\t\t<string>public.item</string>\n\t</array>", "com.apple.Automator.fileSystemObject")
        } else {
            ("<key>NSSendTypes</key>\n\t<array/>", "com.apple.Automator.nothing")
        };
        let info = format!(
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n<plist version=\"1.0\">\n<dict>\n\t<key>CFBundleInfoDictionaryVersion</key>\n\t<string>6.0</string>\n\t<key>CFBundleName</key>\n\t<string>{name}</string>\n\t<key>NSServices</key>\n\t<array>\n\t\t<dict>\n\t\t\t<key>NSBackgroundColorName</key>\n\t\t\t<string>background</string>\n\t\t\t<key>NSMenuItem</key>\n\t\t\t<dict>\n\t\t\t\t<key>default</key>\n\t\t\t\t<string>{menu}</string>\n\t\t\t</dict>\n\t\t\t<key>NSMessage</key>\n\t\t\t<string>runWorkflowAsService</string>\n\t\t\t{send_file_types}\n\t\t</dict>\n\t</array>\n</dict>\n</plist>\n"
        );
        let escaped = script
            .replace('&', "&amp;")
            .replace('<', "&lt;")
            .replace('>', "&gt;");
        let wflow = format!(
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n<plist version=\"1.0\">\n<dict>\n\t<key>AMApplicationBuild</key>\n\t<string>528</string>\n\t<key>AMApplicationVersion</key>\n\t<string>2.10</string>\n\t<key>AMDocumentVersion</key>\n\t<string>2</string>\n\t<key>actions</key>\n\t<array>\n\t\t<dict>\n\t\t\t<key>action</key>\n\t\t\t<dict>\n\t\t\t\t<key>AMAccepts</key>\n\t\t\t\t<dict>\n\t\t\t\t\t<key>Container</key>\n\t\t\t\t\t<string>List</string>\n\t\t\t\t\t<key>Optional</key>\n\t\t\t\t\t<true/>\n\t\t\t\t\t<key>Types</key>\n\t\t\t\t\t<array>\n\t\t\t\t\t\t<string>com.apple.cocoa.path</string>\n\t\t\t\t\t</array>\n\t\t\t\t</dict>\n\t\t\t\t<key>AMActionVersion</key>\n\t\t\t\t<string>2.0.3</string>\n\t\t\t\t<key>AMApplication</key>\n\t\t\t\t<array>\n\t\t\t\t\t<string>Automator</string>\n\t\t\t\t</array>\n\t\t\t\t<key>AMParameterProperties</key>\n\t\t\t\t<dict>\n\t\t\t\t\t<key>COMMAND_STRING</key>\n\t\t\t\t\t<dict/>\n\t\t\t\t\t<key>CheckedForUserDefaultShell</key>\n\t\t\t\t\t<dict/>\n\t\t\t\t\t<key>inputMethod</key>\n\t\t\t\t\t<dict/>\n\t\t\t\t\t<key>shell</key>\n\t\t\t\t\t<dict/>\n\t\t\t\t\t<key>source</key>\n\t\t\t\t\t<dict/>\n\t\t\t\t</dict>\n\t\t\t\t<key>AMProvides</key>\n\t\t\t\t<dict>\n\t\t\t\t\t<key>Container</key>\n\t\t\t\t\t<string>List</string>\n\t\t\t\t\t<key>Types</key>\n\t\t\t\t\t<array>\n\t\t\t\t\t\t<string>com.apple.cocoa.string</string>\n\t\t\t\t\t</array>\n\t\t\t\t</dict>\n\t\t\t\t<key>ActionBundlePath</key>\n\t\t\t\t<string>/System/Library/Automator/Run Shell Script.action</string>\n\t\t\t\t<key>ActionName</key>\n\t\t\t\t<string>Run Shell Script</string>\n\t\t\t\t<key>ActionParameters</key>\n\t\t\t\t<dict>\n\t\t\t\t\t<key>COMMAND_STRING</key>\n\t\t\t\t\t<string>{escaped}</string>\n\t\t\t\t\t<key>CheckedForUserDefaultShell</key>\n\t\t\t\t\t<false/>\n\t\t\t\t\t<key>inputMethod</key>\n\t\t\t\t\t<integer>1</integer>\n\t\t\t\t\t<key>shell</key>\n\t\t\t\t\t<string>/bin/bash</string>\n\t\t\t\t\t<key>source</key>\n\t\t\t\t\t<string></string>\n\t\t\t\t</dict>\n\t\t\t\t<key>BundleIdentifier</key>\n\t\t\t\t<string>com.apple.RunShellScript</string>\n\t\t\t\t<key>CFBundleVersion</key>\n\t\t\t\t<string>2.0.3</string>\n\t\t\t\t<key>CanShowSelectedItemsWhenRun</key>\n\t\t\t\t<string>CanShowWhenRun</string>\n\t\t\t\t<key>CanShowWhenRun</key>\n\t\t\t\t<string>CanShowWhenRun</string>\n\t\t\t\t<key>Category</key>\n\t\t\t\t<array>\n\t\t\t\t\t<string>NMCategory</string>\n\t\t\t\t</array>\n\t\t\t\t<key>Class Name</key>\n\t\t\t\t<string>RunShellScriptAction</string>\n\t\t\t\t<key>InputUUID</key>\n\t\t\t\t<string>6A7C0FCA-KETRA-INPUT-UUID</string>\n\t\t\t\t<key>Keywords</key>\n\t\t\t\t<array>\n\t\t\t\t\t<string>Shell</string>\n\t\t\t\t</array>\n\t\t\t\t<key>OutputUUID</key>\n\t\t\t\t<string>6A7C0FCA-KETRA-OUTPUT-UUID</string>\n\t\t\t\t<key>UUID</key>\n\t\t\t\t<string>6A7C0FCA-KETRA-ACTION-UUID</string>\n\t\t\t\t<key>UnlocalizedApplications</key>\n\t\t\t\t<array>\n\t\t\t\t\t<string>Automator</string>\n\t\t\t\t</array>\n\t\t\t\t<key>arguments</key>\n\t\t\t\t<dict>\n\t\t\t\t\t<key>0</key>\n\t\t\t\t\t<dict>\n\t\t\t\t\t\t<key>default value</key>\n\t\t\t\t\t\t<integer>0</integer>\n\t\t\t\t\t\t<key>name</key>\n\t\t\t\t\t\t<string>inputMethod</string>\n\t\t\t\t\t\t<key>required</key>\n\t\t\t\t\t\t<string>0</string>\n\t\t\t\t\t\t<key>type</key>\n\t\t\t\t\t\t<string>0</string>\n\t\t\t\t\t\t<key>uuid</key>\n\t\t\t\t\t\t<string>0</string>\n\t\t\t\t\t</dict>\n\t\t\t\t</dict>\n\t\t\t\t<key>isViewVisible</key>\n\t\t\t\t<integer>1</integer>\n\t\t\t\t<key>location</key>\n\t\t\t\t<string>309.000000:253.000000</string>\n\t\t\t\t<key>nibPath</key>\n\t\t\t\t<string>/System/Library/Automator/Run Shell Script.action/Contents/Resources/Base.lproj/main.nib</string>\n\t\t\t</dict>\n\t\t\t<key>isViewVisible</key>\n\t\t\t<integer>1</integer>\n\t\t</dict>\n\t</array>\n\t<key>connectors</key>\n\t<dict/>\n\t<key>workflowMetaData</key>\n\t<dict>\n\t\t<key>inputTypeIdentifier</key>\n\t\t<string>{input_type}</string>\n\t\t<key>outputTypeIdentifier</key>\n\t\t<string>com.apple.Automator.nothing</string>\n\t\t<key>presentationMode</key>\n\t\t<integer>11</integer>\n\t\t<key>savesInput</key>\n\t\t<integer>0</integer>\n\t\t<key>workflowTypeIdentifier</key>\n\t\t<string>com.apple.Automator.services</string>\n\t</dict>\n</dict>\n</plist>\n"
        );
        std::fs::write(bundle.join("Info.plist"), info).map_err(|e| e.to_string())?;
        std::fs::write(bundle.join("document.wflow"), wflow).map_err(|e| e.to_string())?;
        Ok(())
    }

    pub fn install() -> Result<(), String> {
        let dir = services_dir();
        std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
        let lookup = ketra_lookup_shell();
        write_workflow(&dir, "KetraCopy Copy", "Copy with KetraCopy", true,
            &format!("{lookup}\nexec \"$KETRA\" clip put \"$@\"\n"))?;
        write_workflow(&dir, "KetraCopy Cut", "Cut with KetraCopy", true,
            &format!("{lookup}\nexec \"$KETRA\" clip put --cut \"$@\"\n"))?;
        write_workflow(&dir, "KetraCopy Move to Folder", "Move with KetraCopy...", true,
            &format!("{lookup}\nDEST=$(/usr/bin/osascript -e 'POSIX path of (choose folder with prompt \"KetraCopy: move into\")' 2>/dev/null)\n[ -z \"$DEST\" ] && exit 0\nexec \"$KETRA\" move \"$@\" -d \"$DEST\" -y --progress auto\n"))?;
        write_workflow(&dir, "KetraCopy Paste", "Paste with KetraCopy", false,
            &format!("{lookup}\nDEST=$(/usr/bin/osascript -e 'POSIX path of (choose folder with prompt \"KetraCopy: paste into\")' 2>/dev/null)\n[ -z \"$DEST\" ] && exit 0\nexec \"$KETRA\" clip paste -d \"$DEST\" -y --progress auto\n"))?;

        // Register the services so they appear without a logout.
        let _ = Command::new("/System/Library/CoreServices/pbs").arg("-flush").status();
        println!("macOS Finder integration installed:");
        println!("  {}", dir.display());
        println!("  Services: Copy with KetraCopy / Cut with KetraCopy / Move with KetraCopy... / Paste with KetraCopy");
        println!("  Enable + assign keyboard shortcuts:");
        println!("    System Settings → Keyboard → Keyboard Shortcuts → Services →");
        println!("    Files and Folders → check the KetraCopy items and add shortcuts.");
        Ok(())
    }

    pub fn uninstall() -> Result<(), String> {
        let dir = services_dir();
        for n in ["KetraCopy Copy", "KetraCopy Cut", "KetraCopy Move to Folder", "KetraCopy Paste"] {
            let _ = std::fs::remove_dir_all(dir.join(format!("{n}.workflow")));
        }
        let _ = Command::new("/System/Library/CoreServices/pbs").arg("-flush").status();
        println!("macOS Finder integration removed");
        Ok(())
    }

    pub fn status() {
        let dir = services_dir();
        for n in ["KetraCopy Copy", "KetraCopy Cut", "KetraCopy Move to Folder", "KetraCopy Paste"] {
            println!(
                "  [{}] {}",
                if dir.join(format!("{n}.workflow")).exists() { "x" } else { " " },
                n
            );
        }
    }
}

// ---------------------------------------------------------------------------
// Dispatch
// ---------------------------------------------------------------------------

fn status_common() {
    println!("ketra {} — shell integration status:", env!("CARGO_PKG_VERSION"));
    println!("  ketra binary: {}", exe_str());
}

pub fn install_cmd(targets: Vec<String>) -> i32 {
    if targets.iter().any(|t| t == "help") {
        println!("targets: windows | linux: nemo nautilus caja dolphin thunar pick shortcuts all | macos: finder-services");
        return 0;
    }
    let r = install_for(targets);
    match r {
        Ok(()) => 0,
        Err(e) => {
            eprintln!("ketra: shell install: {e}");
            1
        }
    }
}

pub fn uninstall_cmd(targets: Vec<String>) -> i32 {
    let r = uninstall_for(targets);
    match r {
        Ok(()) => 0,
        Err(e) => {
            eprintln!("ketra: shell uninstall: {e}");
            1
        }
    }
}

pub fn status_cmd() -> i32 {
    status_common();
    status_for();
    0
}

#[cfg(windows)]
fn install_for(targets: Vec<String>) -> Result<(), String> {
    imp::install()
}
#[cfg(windows)]
fn uninstall_for(_targets: Vec<String>) -> Result<(), String> {
    imp::uninstall()
}
#[cfg(windows)]
fn status_for() {
    imp::status()
}

#[cfg(all(unix, not(target_os = "macos")))]
fn install_for(targets: Vec<String>) -> Result<(), String> {
    imp::install(&targets)
}
#[cfg(all(unix, not(target_os = "macos")))]
fn uninstall_for(targets: Vec<String>) -> Result<(), String> {
    imp::uninstall(&targets)
}
#[cfg(all(unix, not(target_os = "macos")))]
fn status_for() {
    imp::status()
}

#[cfg(target_os = "macos")]
fn install_for(_targets: Vec<String>) -> Result<(), String> {
    imp::install()
}
#[cfg(target_os = "macos")]
fn uninstall_for(_targets: Vec<String>) -> Result<(), String> {
    imp::uninstall()
}
#[cfg(target_os = "macos")]
fn status_for() {
    imp::status()
}
